values
('gold-standard-100-whey', 'Gold Standard 100% Whey', 'proteinas', 189900, 29, 'tarro', '1,98 lb (899 g), 29 porciones', '24 g de proteína y 5,5 g de BCAA por porción. Aislado de suero como fuente principal.', 'Proteína en polvo Gold Standard 100% Whey de Optimum Nutrition, sabor Strawberries & Cream (fresas con crema, saborizado artificialmente). Según su etiqueta aporta 24 g de proteína y 5,5 g de BCAA por porción, su fuente principal es el aislado de proteína de suero (whey protein isolate) y es probado contra sustancias prohibidas. Envase de 1,98 lb (899 g) con 29 porciones.', '["Para apoyo y recuperación muscular (For muscle support & recovery).","24 g de proteína por porción que ayudan a construir y mantener músculo.","5,5 g de BCAA por porción que apoyan la recuperación muscular."]'::jsonb, '[{"k":"Proteína","v":"24 g","por":"por porción"},{"k":"BCAA","v":"5,5 g","por":"por porción"},{"k":"Porciones","v":"29","por":"por envase"},{"k":"Banned substance tested","v":"Sí","por":"probado contra sustancias prohibidas"}]'::jsonb, null, null, array['Gold Standard 100% Whey', 'proteína Optimum Nutrition', 'whey protein Colombia', 'proteína fresas con crema']::text[], '[{"slug":"strawberries-cream","nombre":"Strawberries & Cream","c1":"#d8283a","c2":"#5e0c16"}]'::jsonb, '[["¿Cuál es la fuente principal de proteína?","El aislado de proteína de suero (whey protein isolate), según la etiqueta del envase."],["¿Cuántas porciones trae?","29 porciones en un envase de 1,98 lb (899 g)."],["¿Dónde veo la tabla nutricional completa?","En el envase. Revísala antes de usarlo, junto con el modo de uso y las advertencias del fabricante."]]'::jsonb, true, 40, 5, 0),
('micronized-creatine-powder', 'Micronized Creatine Powder', 'rendimiento', 99900, 60, 'tarro', '300 g (10,58 oz), 60 porciones', '5 g de creatina monohidratada por porción. 100 % creatina monohidratada pura, sin sabor.', 'Creatina micronizada en polvo de Optimum Nutrition, sin sabor (Unflavored). Según su etiqueta es 100 % creatina monohidratada pura, aporta 5 g por porción y es probada contra sustancias prohibidas. La etiqueta indica que la creatina apoya la construcción muscular cuando se toma con el tiempo junto con ejercicio. Envase de 300 g (10,58 oz) con 60 porciones.', '["Para apoyar la construcción muscular (For muscle building support).","100 % creatina monohidratada pura que apoya los movimientos explosivos.","5 g por porción que apoyan la fuerza y la potencia muscular."]'::jsonb, '[{"k":"Creatina","v":"5 g","por":"monohidratada, por porción"},{"k":"Pureza","v":"100 %","por":"creatina monohidratada"},{"k":"Porciones","v":"60","por":"por envase"},{"k":"Sabor","v":"Sin sabor","por":"Unflavored"}]'::jsonb, null, null, array['creatina Optimum Nutrition', 'creatina micronizada', 'creatina monohidratada Colombia']::text[], '[{"slug":"sin-sabor","nombre":"Sin sabor","c1":"#2f9a4a","c2":"#103b1d"}]'::jsonb, '[["¿Qué contiene?","Creatina monohidratada: 100 % pura y 5 g por porción, según la etiqueta."],["¿Cuántas porciones trae?","60 porciones en un envase de 300 g (10,58 oz)."],["¿Dónde veo el modo de uso?","En el envase. Sigue las indicaciones y advertencias del fabricante."]]'::jsonb, true, 40, 5, 1),
('venom-inferno', 'Venom Inferno', 'rendimiento', 129900, null, 'lata', '280 g (9,87 oz)', 'Pre-entreno de estimulación extrema (Extreme High Stim Pre-Workout), sabor Cotton Candy.', 'Venom Inferno de Dragon Pharma es un suplemento dietario pre-entreno de estimulación extrema (Extreme High Stim Pre-Workout), sabor Cotton Candy (algodón de azúcar). Envase de 280 g (9,87 oz).', '["Pre-entreno de estimulación extrema, según la etiqueta.","Sabor Cotton Candy (algodón de azúcar).","Envase de 280 g (9,87 oz)."]'::jsonb, '[{"k":"Tipo","v":"Pre-entreno","por":"Extreme High Stim"},{"k":"Contenido","v":"280 g","por":"9,87 oz"},{"k":"Sabor","v":"Cotton Candy","por":"algodón de azúcar"},{"k":"Marca","v":"Dragon Pharma","por":"fabricante"}]'::jsonb, null, null, array['Venom Inferno', 'pre entreno Dragon Pharma', 'pre workout Colombia']::text[], '[{"slug":"cotton-candy","nombre":"Cotton Candy","c1":"#d3141e","c2":"#2a0507"}]'::jsonb, '[["¿Es fuerte?","La etiqueta lo describe como un pre-entreno de estimulación extrema (Extreme High Stim). Lee las advertencias del envase antes de usarlo."],["¿Dónde veo los ingredientes y la dosis?","En la tabla del envase. Sigue las indicaciones y advertencias del fabricante."]]'::jsonb, true, 40, 5, 2),
('bcaa-2-1-1-watermelon-candy', 'BCAA 2:1:1 Watermelon Candy', 'rendimiento', 109900, 30, 'tarro', '600 g (21,16 oz), 30 servicios', 'BCAA en proporción 2:1:1 (6 g) con sales de electrolitos. Sabor sandía chicle, con stevia.', 'Alimento en polvo a base de maltodextrina con aminoácidos esenciales de cadena ramificada en proporción 2:1:1 (6 g) y sales de electrolitos. Sabor Watermelon Candy (sandía chicle), con polvo de fresa pulverizada y stevia. Su etiqueta lleva el sello "Contiene edulcorantes" (MinSalud). Envase de 600 g (21,16 oz) con 30 servicios.', '["BCAA en proporción 2:1:1 (6 g).","Con sales de electrolitos.","Con aminoácidos esenciales de cadena ramificada."]'::jsonb, '[{"k":"BCAA","v":"6 g","por":"proporción 2:1:1"},{"k":"Electrolitos","v":"Sí","por":"sales de electrolitos"},{"k":"Servicios","v":"30","por":"por envase"},{"k":"Endulzado","v":"Stevia","por":"contiene edulcorantes"}]'::jsonb, null, null, array['BCAA 2:1:1', 'aminoácidos ramificados', 'BCAA sandía', 'BCAA con electrolitos']::text[], '[{"slug":"watermelon-candy","nombre":"Watermelon Candy","c1":"#e2335f","c2":"#6d0f2a"}]'::jsonb, '[["¿Qué significa 2:1:1?","Es la proporción de los tres aminoácidos de cadena ramificada que indica la etiqueta (6 g en total)."],["¿Tiene azúcar o edulcorantes?","La etiqueta lleva el sello \"Contiene edulcorantes\" (MinSalud) e indica stevia. Es un alimento en polvo a base de maltodextrina."]]'::jsonb, true, 40, 5, 3),
('fit-bar-chocolate', 'Fit Bar Chocolate', 'proteinas', 12900, null, 'caja', 'Barra de 60 g', '25 g de proteína por barra, con whey protein isolate. Sabor chocolate.', 'Barra de proteína Fit Bar de Nutramerican, sabor chocolate, con whey protein isolate (proteína de suero). Según su empaque aporta 25 g de proteína por barra. Contenido neto: 60 g.', '["25 g de proteína por barra.","Con whey protein isolate (proteína de suero).","Barra de 60 g para llevar."]'::jsonb, '[{"k":"Proteína","v":"25 g","por":"por barra"},{"k":"Fuente","v":"Whey isolate","por":"proteína de suero"},{"k":"Contenido","v":"60 g","por":"una barra"},{"k":"Sabor","v":"Chocolate","por":"flavor / sabor"}]'::jsonb, null, null, array['Fit Bar', 'barra de proteína', 'barra proteica Nutramerican', 'barra de proteína chocolate']::text[], '[{"slug":"chocolate","nombre":"Chocolate","c1":"#6b3f2c","c2":"#1d0f09"}]'::jsonb, '[["¿Cuánta proteína tiene?","25 g de proteína por barra, según el empaque."],["¿Cuánto pesa?","Contenido neto de 60 g."]]'::jsonb, true, 40, 5, 4),
